Consider the following C code snippet executed in a Linux environment:
```c
#include <stdio.h>
#include <unistd.h>

int main() {
    for (int i = 0; i < 2; i++) {
        if (fork() == 0) {
            printf("*\n");
        }
    }
    return 0;
}
```
Assuming all `fork()` system calls succeed, the total number of times `*` is printed is _________.

Consider the following program in C:

#include <stdio.h>

int fun(int n) {
    static int count = 0;
    if (n <= 0)
        return count;
    count += n;
    int a = fun(n - 1);
    int b = fun(n - 2);
    return a + b;
}

int main() {
    printf("%d", fun(3));
    return 0;
}

The output of the program is ________. (Answer in integer)

Consider the following recursive function written in C:

#include <stdio.h>

int fun(int n) {
    if (n <= 0)
        return 0;
    if (n % 2 == 0)
        return fun(n / 2) + n;
    else
        return fun(n - 1) + 1;
}

int main() {
    printf("%d", fun(15));
    return 0;
}

The output of the program is ________. (Answer in integer)
